from __future__ import annotations

import json
from dataclasses import dataclass
from typing import TYPE_CHECKING, cast
from urllib.parse import urlencode
from urllib.request import Request, urlopen

if TYPE_CHECKING:
    from collections.abc import Iterable

HF_ENDPOINT = "https://huggingface.co"
SEMANTIC_SEARCH_PATH = "/api/spaces/semantic-search"
USER_AGENT = "discover/0.1"


@dataclass
class SpaceRuntime:
    stage: str | None
    raw: dict[str, object]


class SpaceSearchResult:
    def __init__(self, data: dict[str, object]) -> None:
        runtime = data.get("runtime")
        runtime_data = cast("dict[str, object]", runtime) if isinstance(runtime, dict) else None
        self.id = _string(data.get("id"))
        self.author = _string(data.get("author"))
        self.title = _string(data.get("title"))
        self.host = _optional_string(data.get("host"))
        self.subdomain = _optional_string(data.get("subdomain"))
        self.emoji = _optional_string(data.get("emoji"))
        self.sdk = _optional_string(data.get("sdk"))
        self.likes = _integer(data.get("likes"))
        self.private = data.get("private") is True
        self.tags = _string_list(data.get("tags"))
        self.runtime = (
            SpaceRuntime(stage=_optional_string(runtime_data.get("stage")), raw=runtime_data)
            if runtime_data is not None
            else None
        )
        self.ai_short_description = _optional_string(data.get("ai_short_description"))
        self.ai_category = _optional_string(data.get("ai_category"))
        self.semantic_relevancy_score = _optional_float(data.get("semanticRelevancyScore"))
        self.trending_score = _optional_integer(data.get("trendingScore"))


class HfSemanticSpaceSearcher:
    def __init__(self, *, endpoint: str = HF_ENDPOINT) -> None:
        self.endpoint = endpoint.rstrip("/")

    def search_spaces(
        self,
        query: str,
        *,
        filter: str | Iterable[str] | None = None,
        sdk: str | list[str] | None = None,
        include_non_running: bool = False,
        token: bool | str | None = None,
        agents: bool = True,
    ) -> Iterable[SpaceSearchResult]:
        params: dict[str, object] = {"q": query}
        if filter is not None:
            params["filter"] = filter
        if sdk is not None:
            params["sdk"] = sdk
        if include_non_running:
            params["includeNonRunning"] = "true"
        if agents:
            params["agents"] = "true"

        url = f"{self.endpoint}{SEMANTIC_SEARCH_PATH}?{urlencode(params, doseq=True)}"
        headers = {"User-Agent": USER_AGENT}
        if isinstance(token, str):
            headers["Authorization"] = f"Bearer {token}"

        request = Request(url, headers=headers)  # noqa: S310 - public HF API endpoint
        with urlopen(request, timeout=30) as response:  # noqa: S310 - public HF API endpoint
            data = json.loads(response.read().decode("utf-8"))

        if not isinstance(data, list):
            return []
        return [SpaceSearchResult(item) for item in data if isinstance(item, dict)]


def _string(value: object) -> str:
    return value if isinstance(value, str) else ""


def _optional_string(value: object) -> str | None:
    return value if isinstance(value, str) else None


def _integer(value: object) -> int:
    return value if isinstance(value, int) else 0


def _optional_integer(value: object) -> int | None:
    return value if isinstance(value, int) else None


def _optional_float(value: object) -> float | None:
    if isinstance(value, int | float):
        return float(value)
    return None


def _string_list(value: object) -> list[str] | None:
    if not isinstance(value, list):
        return None
    return [item for item in value if isinstance(item, str)]

from __future__ import annotations

from fastapi.testclient import TestClient

from discover.challenge import (
    A2A_AGENT_MEDIA_TYPE,
    AI_CATALOG_MEDIA_TYPE,
    AI_REGISTRY_MEDIA_TYPE,
    create_challenge_app,
)
from discover.hf_spaces import AI_SKILL_MEDIA_TYPE, MCP_SERVER_MEDIA_TYPE


def test_challenge_root_search_returns_mixed_result_types_and_referrals() -> None:
    client = TestClient(create_challenge_app())

    response = client.post(
        "/search",
        json={
            "query": {"text": "find tools registries and skills"},
            "federation": "referrals",
            "pageSize": 20,
        },
    )

    assert response.status_code == 200
    body = response.json()
    media_types = {result["type"] for result in body["results"]}
    assert {
        AI_SKILL_MEDIA_TYPE,
        MCP_SERVER_MEDIA_TYPE,
        A2A_AGENT_MEDIA_TYPE,
        AI_CATALOG_MEDIA_TYPE,
        AI_REGISTRY_MEDIA_TYPE,
    } <= media_types
    assert {referral["type"] for referral in body["referrals"]} == {AI_REGISTRY_MEDIA_TYPE}


def test_challenge_search_filters_by_media_type() -> None:
    client = TestClient(create_challenge_app())

    response = client.post(
        "/search",
        json={
            "query": {"text": "tool server", "filter": {"type": [MCP_SERVER_MEDIA_TYPE]}},
            "pageSize": 10,
        },
    )

    assert response.status_code == 200
    results = response.json()["results"]
    assert results
    assert {result["type"] for result in results} == {MCP_SERVER_MEDIA_TYPE}


def test_challenge_search_filters_by_publisher_and_metadata_field_path() -> None:
    client = TestClient(create_challenge_app())

    response = client.post(
        "/search",
        json={
            "query": {
                "text": "tool server",
                "filter": {
                    "publisher": "discover.dev",
                    "metadata.sourceType": "challenge-mcp",
                },
            },
            "pageSize": 10,
        },
    )

    assert response.status_code == 200
    results = response.json()["results"]
    assert results
    assert {result["type"] for result in results} == {MCP_SERVER_MEDIA_TYPE}


def test_challenge_nested_registry_refers_to_deep_registry() -> None:
    client = TestClient(create_challenge_app())

    response = client.post(
        "/registries/nested/search",
        json={
            "query": {"text": "walk deeper registries"},
            "federation": "referrals",
            "pageSize": 5,
        },
    )

    assert response.status_code == 200
    body = response.json()
    assert body["referrals"][0]["url"].endswith("/registries/deep/search")

    deep_response = client.post(
        "/registries/deep/search",
        json={"query": {"text": "leaf artifacts"}, "pageSize": 5},
    )
    assert deep_response.status_code == 200
    assert {result["type"] for result in deep_response.json()["results"]} == {
        AI_SKILL_MEDIA_TYPE,
        MCP_SERVER_MEDIA_TYPE,
    }


def test_challenge_artifact_routes_are_fetchable() -> None:
    client = TestClient(create_challenge_app())

    skill_response = client.get("/artifacts/skills/triage-skill/SKILL.md")
    mcp_response = client.get("/artifacts/mcp/echo-tools")
    catalog_response = client.get("/.well-known/ai-catalog.json")

    assert skill_response.status_code == 200
    assert 'name: "triage-skill"' in skill_response.text
    assert mcp_response.status_code == 200
    assert mcp_response.json()["tools"][0]["name"] == "challenge_echo"
    assert catalog_response.status_code == 200
    assert catalog_response.json()["host"]["displayName"] == "ARD Challenge Registry"


def test_challenge_explore_returns_not_implemented() -> None:
    client = TestClient(create_challenge_app())

    response = client.post("/explore", json={"query": {}, "resultType": {"facets": []}})

    assert response.status_code == 501

from __future__ import annotations

from importlib.metadata import entry_points, version
from inspect import signature
from typing import Any, cast

import typer
from pydantic import ValidationError
from typer.main import get_command
from typer.testing import CliRunner

from discover import cli, server
from discover.models import SearchResponse

app = cli.app


class RecordingFetchSpaceInfo:
    def __init__(self, tags: list[str] | None = None) -> None:
        self.calls: list[tuple[str, bool | str | None]] = []
        self.space = server.HfSpaceInfo(
            id="alice/mcp",
            author="alice",
            title="Alice MCP",
            host="https://alice-mcp.hf.space",
            subdomain="alice-mcp",
            emoji=None,
            sdk="gradio",
            likes=1,
            private=False,
            tags=tags or ["gradio", "mcp-server"],
            runtime=server.HfSpaceRuntimeInfo(stage="RUNNING", raw={"stage": "RUNNING"}),
            ai_short_description="Alice MCP tools.",
            ai_category=None,
            semantic_relevancy_score=None,
            trending_score=None,
            card_data={"title": "Alice MCP", "license": "mit"},
        )

    def __call__(self, space_id: str, *, token: bool | str | None = None) -> server.HfSpaceInfo:
        self.calls.append((space_id, token))
        return self.space


def test_version_option_prints_installed_project_version() -> None:
    result = CliRunner().invoke(app, ["--version"])

    assert result.exit_code == 0
    assert result.output == f"hf-discover {version('hf-discover')}\n"


def test_version_command_prints_installed_project_version() -> None:
    result = CliRunner().invoke(app, ["version"])

    assert result.exit_code == 0
    assert result.output == f"hf-discover {version('hf-discover')}\n"


def test_package_exposes_hf_extension_console_script() -> None:
    scripts = entry_points(group="console_scripts")

    assert scripts["hf-discover"].value == "discover.cli:app"
    assert [script.name for script in scripts if script.value == "discover.cli:app"] == [
        "hf-discover",
    ]


def test_search_commands_default_to_hosted_registry_urls() -> None:
    search_parameters = signature(cli.search_alias).parameters

    assert search_parameters["registry_url"].default == cli.DEFAULT_REGISTRY_URL
    assert search_parameters["base_url"].default == cli.DEFAULT_REGISTRY_URL
    assert search_parameters["local"].default is False


def test_search_command_hides_local_base_url_escape_hatch() -> None:
    command = cast("Any", get_command(app)).commands["search"]
    options_by_name = {parameter.name: parameter for parameter in command.params}

    assert options_by_name["registry_url"].hidden is False
    assert options_by_name["local"].hidden is False
    assert options_by_name["base_url"].hidden is True


def test_mcp_server_json_command_is_registered() -> None:
    command = cast("Any", get_command(app))

    assert "mcp-server-json" in command.commands


def test_mcp_server_json_helper_fetches_space_and_builds_descriptor() -> None:
    fetch_space = RecordingFetchSpaceInfo()
    token = f"hf_{'test-token'}"

    payload = cli._mcp_server_json_for_space(
        "alice/mcp",
        token=token,
        fetch_space=fetch_space,
    )

    assert fetch_space.calls == [("alice/mcp", token)]
    assert payload["name"] == "hf-space-alice-mcp"
    assert payload["description"] == "Alice MCP tools."
    assert payload["remotes"] == [
        {"type": "streamable-http", "url": "https://alice-mcp.hf.space/gradio_api/mcp/"}
    ]


def test_mcp_server_json_helper_rejects_non_mcp_spaces() -> None:
    fetch_space = RecordingFetchSpaceInfo(tags=["gradio"])

    try:
        cli._mcp_server_json_for_space("alice/not-mcp", fetch_space=fetch_space)
    except typer.BadParameter as exc:
        message = str(exc)
    else:
        raise AssertionError("expected non-MCP Space to fail")

    assert "not tagged as an MCP server" in message


def test_registry_response_error_message_explains_missing_v5_type_field() -> None:
    try:
        SearchResponse.model_validate(
            {
                "results": [
                    {
                        "identifier": "urn:air:example.com:skill",
                        "displayName": "Example Skill",
                        "url": "https://example.com/SKILL.md",
                        "score": 91,
                        "source": "https://example.com",
                    }
                ]
            }
        )
    except ValidationError as exc:
        message = cli._registry_response_error_message(exc)
    else:
        raise AssertionError("expected malformed SearchResponse to fail validation")

    assert "not an ARD v0.5 SearchResponse" in message
    assert "results.0.type" in message
    assert "include `type` media types" in message
    assert "older pre-v0.5 schema" in message


def test_registry_response_error_message_summarizes_many_missing_fields() -> None:
    try:
        SearchResponse.model_validate(
            {
                "results": [
                    {
                        "identifier": f"urn:air:example.com:skill:{index}",
                        "displayName": f"Example Skill {index}",
                        "url": f"https://example.com/{index}/SKILL.md",
                        "score": 91,
                        "source": "https://example.com",
                    }
                    for index in range(6)
                ]
            }
        )
    except ValidationError as exc:
        message = cli._registry_response_error_message(exc)
    else:
        raise AssertionError("expected malformed SearchResponse to fail validation")

    assert "results.0.type" in message
    assert "results.4.type" in message
    assert "results.5.type" not in message
    assert "(6 total)" in message

